<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { ArrowLeftRight, ArrowDownLeft, ArrowUpRight, CheckCircle2, Wallet, RefreshCw, Copy } from 'lucide-vue-next'
import { get, post, money } from '../services/api'
const groups=ref([]), groupId=ref(''), balances=ref([]), plan=ref([]), settlements=ref([]), loading=ref(false), error=ref(''), payer=ref(''), receiver=ref(''), amount=ref(''), note=ref(''), saving=ref(false), message=ref('')
const selectedGroup=computed(()=>groups.value.find(g=>String(g.id)===String(groupId.value)))
const creditors=computed(()=>balances.value.filter(b=>b.balance_paise>0))
const debtors=computed(()=>balances.value.filter(b=>b.balance_paise<0))
async function loadGroups(){try{groups.value=await get('/groups');if(!groupId.value&&groups.value.length)groupId.value=String(groups.value[0].id)}catch(e){error.value=e.message}}
async function load(){if(!groupId.value)return;loading.value=true;error.value='';try{[balances.value,plan.value,settlements.value]=await Promise.all([get(`/groups/${groupId.value}/balances`),get(`/groups/${groupId.value}/settlement-plan`),get(`/groups/${groupId.value}/settlements`)]);payer.value='';receiver.value='';amount.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
watch(groupId,load)
onMounted(loadGroups)
async function settle(){error.value='';message.value='';if(!payer.value||!receiver.value||!amount.value){error.value='Choose a payer, receiver, and amount.';return}saving.value=true;try{await post('/settlements',{group_id:Number(groupId.value),payer_id:Number(payer.value),receiver_id:Number(receiver.value),amount:Number(amount.value),note:note.value});message.value='Repayment recorded and balances updated.';note.value='';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
function fillSuggestion(p){payer.value=String(p.payer_id);receiver.value=String(p.receiver_id);amount.value=p.amount}
async function copyPlan(){const text=plan.value.length?plan.value.map(p=>`${p.payer_name} pays ${p.receiver_name} ${money(p.amount)}`).join('\n'):'Everyone is settled up.';try{await navigator.clipboard.writeText(`${selectedGroup.value?.name || 'SplitFlow settlement'}\n${text}`);message.value='Settlement summary copied.'}catch{message.value=text}}
</script>
<template>
  <div class="page-stack">
    <section class="page-intro"><div><div class="eyebrow">CLEAR THE TAB</div><h2>Let's settle up.</h2><p>Know exactly who owes whom, with fewer unnecessary transfers.</p></div><div v-if="groups.length" class="group-select"><label>Current group</label><select v-model="groupId"><option v-for="g in groups" :key="g.id" :value="String(g.id)">{{ g.name }}</option></select></div></section>
    <p v-if="error" class="alert alert-error">{{ error }}</p><p v-if="message" class="alert alert-success">{{ message }}</p>
    <div v-if="!groups.length" class="panel empty-state large-empty"><div class="empty-icon"><ArrowLeftRight :size="25"/></div><h3>No group to settle.</h3><p>Create a group and add expenses to see balances here.</p><RouterLink to="/groups" class="btn btn-primary">Create a group</RouterLink></div>
    <template v-else>
      <div class="settlement-summary"><div class="settlement-summary-copy"><span class="welcome-chip"><CheckCircle2 :size="13"/> BALANCE OVERVIEW</span><h3>Clarity is a good feeling.</h3><p>{{ selectedGroup?.name }} · {{ balances.length }} members</p></div><div class="summary-total"><span>Group expenses</span><strong>{{ money(selectedGroup?.total_expenses) }}</strong></div><div class="summary-total"><span>Suggested transfers</span><strong>{{ plan.length }}</strong></div></div>
      <div class="balance-grid"><section class="panel"><div class="panel-heading"><div><h3>Member balances</h3><p>Positive means they're owed; negative means they owe.</p></div><button class="icon-btn" @click="load" title="Refresh"><RefreshCw :size="16"/></button></div><div v-if="loading" class="empty-state">Calculating balances…</div><div v-else class="balance-list"><div v-for="b in balances" :key="b.member_id" class="balance-row"><span class="mini-avatar">{{ b.name.slice(0,1).toUpperCase() }}</span><div class="balance-person"><strong>{{ b.name }}</strong><span>{{ b.balance_paise>0?'Should receive':b.balance_paise<0?'Owes the group':'All settled' }}</span></div><strong class="balance-value" :class="b.balance_paise>0?'positive':b.balance_paise<0?'negative':''">{{ b.balance_paise>0?'+':b.balance_paise<0?'−':'' }}{{ money(Math.abs(b.balance)) }}</strong></div><div v-if="balances.length" class="balance-foot"><CheckCircle2 :size="15"/> Net balances reconcile to zero</div></div></section>
      <section class="panel"><div class="panel-heading"><div><h3>Smart settlement plan</h3><p>Suggested payments to clear the group's net balances.</p></div><button class="icon-btn" @click="copyPlan" title="Copy plan"><Copy :size="16"/></button></div><div v-if="!plan.length" class="settled-state"><div class="settled-icon"><CheckCircle2 :size="28"/></div><strong>You're all settled up!</strong><p>No outstanding repayments in this group.</p></div><div v-else class="plan-list"><button v-for="(p,i) in plan" :key="i" class="plan-row" @click="fillSuggestion(p)"><div class="plan-avatars"><span>{{ p.payer_name.slice(0,1) }}</span><ArrowRightIcon/><span>{{ p.receiver_name.slice(0,1) }}</span></div><div class="plan-people"><strong>{{ p.payer_name }} <span>pays</span> {{ p.receiver_name }}</strong><small>Tap to record this repayment</small></div><strong class="plan-amount">{{ money(p.amount) }}</strong></button><div class="plan-note"><CheckCircle2 :size="15"/> A suggested transfer is not recorded until you confirm it.</div></div></section></div>
      <section class="panel settle-form-panel"><div class="panel-heading"><div><h3>Record a repayment</h3><p>Record money already paid between two group members.</p></div><div class="form-title-icon"><ArrowLeftRight :size="19"/></div></div><form @submit.prevent="settle" class="settle-form"><label>Who pays?<select v-model="payer" required><option value="" disabled>Select payer</option><option v-for="m in debtors" :key="m.member_id" :value="String(m.member_id)">{{ m.name }} (owes {{ money(Math.abs(m.balance)) }})</option></select></label><div class="transfer-arrow"><ArrowRightIcon :size="18"/></div><label>Who receives?<select v-model="receiver" required><option value="" disabled>Select receiver</option><option v-for="m in creditors" :key="m.member_id" :value="String(m.member_id)">{{ m.name }} (owed {{ money(m.balance) }})</option></select></label><label>Amount (₹)<input v-model="amount" type="number" min=".01" step=".01" required placeholder="0.00"/></label><label>Note (optional)<input v-model="note" placeholder="e.g. UPI repayment"/></label><button class="btn btn-primary" :disabled="saving"><CheckCircle2 :size="16"/>{{ saving?'Recording…':'Confirm repayment' }}</button></form></section>
      <section class="panel"><div class="panel-heading"><div><h3>Settlement history</h3><p>Repayments that have actually been recorded.</p></div></div><div v-if="!settlements.length" class="empty-state compact">No repayments recorded yet.</div><div v-else class="expense-table"><div v-for="s in settlements" :key="s.id" class="expense-row"><div class="expense-symbol cat-groceries"><ArrowLeftRight :size="17"/></div><div class="expense-info"><strong>{{ s.payer_name }} → {{ s.receiver_name }}</strong><span>{{ s.note || 'Repayment recorded' }}</span></div><div class="expense-amount"><strong>{{ money(s.amount) }}</strong><span>{{ new Date(s.created_at).toLocaleDateString() }}</span></div></div></div></section>
    </template>
  </div>
</template>
<script>
import { ArrowRight as ArrowRightIcon } from 'lucide-vue-next'
export default { components: { ArrowRightIcon } }
</script>
